ALTER TABLE organizations MODIFY kind ENUM('school','college','corporate') NOT NULL;
CREATE TABLE grades (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,name VARCHAR(100) NOT NULL,UNIQUE(org_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE sections (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,grade_id CHAR(36) NOT NULL,name VARCHAR(100) NOT NULL,UNIQUE(grade_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(grade_id) REFERENCES grades(id)) ENGINE=InnoDB;
CREATE TABLE subjects (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,code VARCHAR(40) NOT NULL DEFAULT '',UNIQUE(org_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id)) ENGINE=InnoDB;
CREATE TABLE batches (id CHAR(36) PRIMARY KEY,org_id CHAR(36) NOT NULL,name VARCHAR(120) NOT NULL,grade_id CHAR(36) NULL,section_id CHAR(36) NULL,start_date DATE NULL,end_date DATE NULL,UNIQUE(org_id,name),FOREIGN KEY(org_id) REFERENCES organizations(id),FOREIGN KEY(grade_id) REFERENCES grades(id),FOREIGN KEY(section_id) REFERENCES sections(id)) ENGINE=InnoDB;
CREATE TABLE batch_members (batch_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,PRIMARY KEY(batch_id,user_id),FOREIGN KEY(batch_id) REFERENCES batches(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE batch_subjects (batch_id CHAR(36) NOT NULL,subject_id CHAR(36) NOT NULL,PRIMARY KEY(batch_id,subject_id),FOREIGN KEY(batch_id) REFERENCES batches(id),FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB;
CREATE TABLE teacher_assignments (batch_id CHAR(36) NOT NULL,subject_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,PRIMARY KEY(batch_id,subject_id,user_id),FOREIGN KEY(batch_id,subject_id) REFERENCES batch_subjects(batch_id,subject_id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE student_subjects (batch_id CHAR(36) NOT NULL,subject_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,PRIMARY KEY(batch_id,subject_id,user_id),FOREIGN KEY(batch_id,user_id) REFERENCES batch_members(batch_id,user_id) ON DELETE CASCADE,FOREIGN KEY(batch_id,subject_id) REFERENCES batch_subjects(batch_id,subject_id)) ENGINE=InnoDB;
CREATE TABLE student_profiles (org_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,admission_number VARCHAR(60) NOT NULL DEFAULT '',birth_date DATE NULL,gender VARCHAR(40) NOT NULL DEFAULT '',phone VARCHAR(40) NOT NULL DEFAULT '',address VARCHAR(500) NOT NULL DEFAULT '',guardian_name VARCHAR(120) NOT NULL DEFAULT '',guardian_phone VARCHAR(40) NOT NULL DEFAULT '',guardian_email VARCHAR(254) NOT NULL DEFAULT '',emergency_contact VARCHAR(160) NOT NULL DEFAULT '',admission_date DATE NULL,PRIMARY KEY(org_id,user_id),FOREIGN KEY(org_id,user_id) REFERENCES memberships(org_id,user_id) ON DELETE CASCADE) ENGINE=InnoDB;
ALTER TABLE courses ADD COLUMN subject_id CHAR(36) NULL, ADD COLUMN access_mode ENUM('organization','assigned') NOT NULL DEFAULT 'organization',ADD FOREIGN KEY(subject_id) REFERENCES subjects(id);
CREATE TABLE course_batches (course_id CHAR(36) NOT NULL,batch_id CHAR(36) NOT NULL,PRIMARY KEY(course_id,batch_id),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(batch_id) REFERENCES batches(id)) ENGINE=InnoDB;
CREATE TABLE course_students (course_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,PRIMARY KEY(course_id,user_id),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE course_materials (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,name VARCHAR(180) NOT NULL,kind ENUM('pdf','pptx') NOT NULL,file_key VARCHAR(100) NOT NULL,file_size INT NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB;
CREATE TABLE assessments (id CHAR(36) PRIMARY KEY,course_id CHAR(36) NOT NULL,author_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,kind ENUM('project','assignment') NOT NULL,instructions TEXT NOT NULL,due_date DATE NULL,max_score INT NOT NULL DEFAULT 100,status ENUM('draft','published') NOT NULL DEFAULT 'draft',created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(course_id) REFERENCES courses(id),FOREIGN KEY(author_id) REFERENCES users(id),CHECK(max_score BETWEEN 1 AND 1000)) ENGINE=InnoDB;
CREATE TABLE submissions (id CHAR(36) PRIMARY KEY,assessment_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,body MEDIUMTEXT NOT NULL,link VARCHAR(2000) NOT NULL DEFAULT '',score INT NULL,feedback TEXT NULL,graded_by CHAR(36) NULL,submitted_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),graded_at DATETIME(3) NULL,UNIQUE(assessment_id,user_id),FOREIGN KEY(assessment_id) REFERENCES assessments(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(graded_by) REFERENCES users(id)) ENGINE=InnoDB;
